const dirRow=el(doc,'div',{class:'fx-gear-row',dataset:{futRelistDirRow:'1'}},
[el(doc,'span',{class:'fx-gear-key',text:t('transfers.gear.direction')}),
el(doc,'span',{class:'fx-gear-pick'},dirs)])
