if(box.cut>0)out.push({id:'cut',key:'transfers.chip.cut',params:{count:box.cut},tone:'fx-cut'})
if(box.dead>0)out.push({id:'dead',key:'transfers.chip.dead',params:{count:box.dead},tone:'fx-dead'})
