function pressBatch(kind,deps){if(batchRun!==null)return{ok:false,reason:'busy'}
const view=typeof deps.read==='function'?deps.read():{rows:deps.rows?.()??[],seen:0,unread:0}
const asked=askBands(kind,view,deps)
if(asked!==null)return asked
const section=batchSectionOf(kind,deps.section??null,view.rows)
const jobs=jobsOf(view.rows,kind,section)
const note=promiseNote(kind,deps.promised,jobs.length,view,deps.t,section)+edgeNote(kind,jobs,view,deps.t)
if(jobs.length===0){armedKind=null
if(note!=='')deps.say(note.trim())
return{ok:false,reason:'empty',note}}
const key=doorConsentKey({action:kind==='club'?'move':'list',
reason:kind==='club'?'batch-'+String(section):'batch-'+kind+'-'+pricingKey(relistPricing),
destination:kind==='club'?'CLUB':'TRANSFER',ids:jobs.map((job)=>job.id)})
if(!batchConsent.ask(key)){armedKind=kind
const question=deps.t(ASK_KEYS[kind]??ASK_KEYS.club,
{count:jobs.length,unit:deps.t(cardsUnitKey(jobs.length)),
rule:deps.t(sayKeyOf(relistPricing),{percent:relistPricing.percent})})+note
+sectionNote(kind,view,deps.t,section)
if(typeof deps.confirm==='function')deps.confirm({text:question,count:jobs.length,
kind,unit:deps.t(cardsUnitKey(jobs.length)),
rule:kind==='club'?null:deps.t(sayKeyOf(relistPricing),{percent:relistPricing.percent}),
parts:sectionParts(kind,view,section),note})
else deps.say(question)
return{ok:false,reason:'consent',count:jobs.length,note}}
armedKind=null
const done=runBatch(kind,jobs,{...deps,note})
done.catch?.(()=>{})
return{ok:true,reason:null,count:jobs.length,done,note}}
function sectionParts(kind,view,section=null){const rows=Array.isArray(view?.rows)?view.rows:[]
const box=summarizeLots(rows)[batchSectionOf(kind,section,rows)]??emptyBox()
const whole=(value)=>Math.max(0,Math.trunc(Number(value)||0))
const total=whole(box?.count)
const promised=whole(box?.[BULK_FIELD_OF_KIND[kind]??'relist'])
const frozen=whole(box?.frozen)
const noPrice=kind==='club'?0:whole(box?.noPrice)
const noMove=kind==='club'?whole(box?.noMove):0
if(frozen+noPrice+noMove+promised!==total)return null
if(frozen+noPrice+noMove===0)return null
return{total,promised,frozen,noPrice,noMove}}
function sectionNote(kind,view,t,section=null){const parts=sectionParts(kind,view,section)
if(parts===null)return ''
const why=[]
if(parts.frozen>0)why.push(t('transfers.chip.frozen',{count:parts.frozen}))
if(parts.noPrice>0)why.push(t('transfers.chip.noPrice',{count:parts.noPrice}))
if(parts.noMove>0)why.push(t('transfers.chip.noMove',{count:parts.noMove}))
return ' '+t('transfers.batch.section',{total:parts.total,taken:parts.promised,why:why.join(', ')})}
function promiseNote(kind,promised,taken,view,t,section=null){const said=Number(promised)
if(!Number.isSafeInteger(said)||said===taken)return ''
const rows=Array.isArray(view?.rows)?view.rows:[]
const unread=Math.max(0,Number(view?.unread)||0)
const box=summarizeLots(rows)[batchSectionOf(kind,section,rows)]??emptyBox()
const why=said<taken?t('transfers.promise.late')
:(taken>=BATCH_CAP?t('transfers.promise.cap',{cap:BATCH_CAP,left:Math.max(0,said-taken)})
:(unread>0?t('transfers.promise.unread',{unread,unit:t(cardsUnitKey(unread))})
:(kind!=='club'&&box.noPrice>0?t('transfers.promise.noPrice',{noPrice:box.noPrice,unit:t(cardsUnitKey(box.noPrice))})
:t('transfers.promise.gone'))))
return ' '+t('transfers.promise.said',{promised:said,taken,why})}
function edgeNote(kind,jobs,view,t){if(kind==='club')return ''
const list=Array.isArray(jobs)?jobs:[]
const atFloor=list.filter((job)=>job?.price?.clamped==='min').length
const atCeil=list.filter((job)=>job?.price?.clamped==='max').length
const noBand=(Array.isArray(view?.rows)?view.rows:[])
.filter((one)=>one?.noBand===true&&one?.frozen!==true&&one?.money?.section===SECTION_OF_KIND[kind]).length
const parts=[]
if(atFloor>0)parts.push(t('transfers.run.atFloor',{count:atFloor}))
if(atCeil>0)parts.push(t('transfers.run.atCeil',{count:atCeil}))
if(noBand>0)parts.push(t('transfers.run.noBand',{count:noBand}))
return parts.length===0?'':' '+parts.join(' · ')}
const SECTION_OF_KIND=Object.freeze({relist:'UNSOLD',list:'AVAILABLE'})
const CLUB_SECTIONS=Object.freeze(['UNSOLD','AVAILABLE'])
const BATCH_KINDS=Object.freeze(['relist','list','club'])
function batchSectionOf(kind,section,rows){if(kind!=='club')return SECTION_OF_KIND[kind]??null
if(section!==null&&section!==undefined)return CLUB_SECTIONS.includes(section)?section:null
const first=(Array.isArray(rows)?rows:[]).find((one)=>one?.money?.section)?.money?.section??null
return CLUB_SECTIONS.includes(first)?first:null}
const BULK_FIELD_OF_KIND=Object.freeze({relist:'relist',list:'list',club:'club'})
const ASK_KEYS=Object.freeze({relist:'transfers.btn.relistAllAsk',
list:'transfers.btn.listAllAsk',club:'transfers.btn.clubAsk'})
